scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_10_cell_2_0').getAttribute('class') == 'w2grid_input_table gridBodyDefault gridBodyDefault_data '+$p.id+'wq_uuid_10_columnstyle_0_ ta';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
